const LLM_INTEGRATIONS: LLMIntegration[] = [
  {
    id: "claude",
    name: "Claude",
    iconSrc: <ClaudeIcon />,
  },
  {
    id: "chatgpt",
    name: "ChatGPT",
    iconSrc: <ChatgptIcon />,
  },
  {
    id: "gemini",
    name: "Gemini",
    iconSrc: <GeminiIcon />,
  },
  {
    id: "perplexity",
    name: "Perplexity",
    iconSrc: <PerplexityIcon />,
  },
];

const DURATION_MS = 4000;

export function LandingTryNow() {
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setActiveIndex((prevIndex) => (prevIndex + 1) % LLM_INTEGRATIONS.length);
    }, DURATION_MS);

    return () => clearInterval(interval);
  }, []);

  const active = LLM_INTEGRATIONS[activeIndex];

  return (
    <SectionWrapper position="middle">
      <section className="px-2 py-20 md:py-24 lg:py-40">
        <div className="mx-auto flex max-w-3xl flex-col gap-8 text-center">
          <div className="space-y-3">
            <div className="flex flex-col gap-3 p-1 text-4xl font-normal leading-[1.12] tracking-tight text-foreground sm:text-4xl md:text-5xl">
              <h2>Connect OpenWork</h2>

              <AnimatePresence mode="popLayout" initial={false}>
                <motion.div
                  key={active.id}
                  className="inline-flex items-center justify-center gap-3"
                  initial={{
                    opacity: 0,
                    y: 6,
                    filter: "blur(10px)",
                  }}
                  animate={{
                    opacity: 1,
                    y: 0,
                    filter: "blur(0px)",
                  }}
                  exit={{
                    opacity: 0,
                    y: -6,
                    filter: "blur(10px)",
                  }}
                  transition={{
                    duration: 0.35,
                    ease: "easeOut",
                  }}
                >
                  <span>with</span>

                  {/* Bigger icon container */}
                  <span className="inline-flex size-8 items-center justify-center">
                    {active.iconSrc}
                  </span>

                  <h2>{active.name}</h2>
                </motion.div>
              </AnimatePresence>
            </div>

            <p className="mx-auto max-w-2xl leading-relaxed text-muted-foreground md:text-xl">
              OpenWork is the desktop app that lets you use 50+ LLMs, bring your
              own keys, and share your setups seamlessly with your team.
            </p>
          </div>

          <div className="mx-auto flex w-full max-w-md flex-col gap-3 sm:flex-row sm:justify-center">
            <a href="/download" className="w-full sm:w-auto">
              <Button size="lg" className="w-full sm:w-auto">
                Download for free
              </Button>
            </a>

            <a href="/enterprise#book" className="w-full sm:w-auto">
              <Button variant="ghost" size="lg" className="w-full sm:w-auto">
                Contact sales
              </Button>
            </a>
          </div>
        </div>
      </section>
    </SectionWrapper>
  );
}
